// Inline HMAC verification — webhook never forwards on bad signature.
const crypto = require('crypto');
const secret = process.env.N8N_SHARED_SECRET;
if (!secret) throw new Error('missing N8N_SHARED_SECRET');
const sig = $input.item.json.headers['x-cofre-signature'] || '';
const body = JSON.stringify($input.item.json.body);
const expected = crypto.createHmac('sha256', secret).update(body).digest('hex');
const ok = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
if (!ok) throw new Error('bad-signature');
return [{ json: $input.item.json.body }];

const fetch = (...a) => globalThis.fetch(...a);
const tg = $json.message.from;
const text = $('Combine Inputs').item.json.text;
const KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
const SUPA = process.env.SUPABASE_URL;
const r = await fetch(SUPA + '/rest/v1/profiles?select=id,first_name,locale,default_currency&telegram_id=eq.' + tg.id, {
  headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }
});
const ownerArr = await r.json();
const owner = ownerArr[0];
const fr = await fetch(SUPA + '/rest/v1/relations?select=friend:friend_id(first_name,last_name,telegram_username)&owner_id=eq.' + owner.id, {
  headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }
});
const friends = (await fr.json() || []).map(x => x.friend);
const tr = await fetch(SUPA + '/rest/v1/tours?select=name,nickname&owner_id=eq.' + owner.id + '&status=eq.active', {
  headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }
});
const tours = await tr.json() || [];
return [{ json: { transcript: text, user: owner, knownFriends: friends, activeTours: tours } }];

const raw = $json.content?.[0]?.text || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch { parsed = { actions: [{ kind: 'unknown', memo: '', confidence: 0 }], language: $('Load Sender Context').item.json.user.locale || 'en' }; }
return [{ json: parsed, _ctx: $('Load Sender Context').item.json }];

const fetch = (...a) => globalThis.fetch(...a);
const SUPA = process.env.SUPABASE_URL, KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
const ctx = $json._ctx, intent = $json;
const ownerId = ctx.user.id;
const friendByName = new Map();
for (const f of ctx.knownFriends) {
  const key = [f.first_name, f.last_name].filter(Boolean).join(' ').toLowerCase();
  friendByName.set(key, f.id);
  friendByName.set((f.telegram_username || '').toLowerCase(), f.id);
}
const tourByNick = new Map();
const tourMembersCache = {};
for (const t of (ctx.activeTours || [])) {
  if (t.nickname) tourByNick.set(String(t.nickname).toLowerCase(), t);
}
const rows = [];
for (const a of (intent.actions || [])) {
  if (a.kind === 'unknown' || !a.amount_cents) continue;
  const cpName = (a.counterparty_name || '').toLowerCase();
  const cpId = friendByName.get(cpName) || null;
  let tourId = null, tourMemberId = null;
  if (a.tour_nickname) {
    const t = tourByNick.get(String(a.tour_nickname).toLowerCase());
    if (t) {
      tourId = t.id;
      if (!tourMembersCache[tourId]) {
        const mr = await fetch(SUPA + '/rest/v1/tour_members?select=id,profile_id&tour_id=eq.' + tourId, {
          headers: { apikey: KEY, Authorization: 'Bearer ' + KEY }
        });
        tourMembersCache[tourId] = (await mr.json() || []);
      }
      const assignName = (a.assign_to_member_name || '').toLowerCase();
      if (assignName) {
        const assignId = friendByName.get(assignName);
        const member = assignId ? tourMembersCache[tourId].find(m => m.profile_id === assignId) : null;
        tourMemberId = member ? member.id : null;
      }
    }
  }
  rows.push({
    owner_id: ownerId,
    counterparty_id: cpId,
    tour_id: tourId,
    tour_member_id: tourMemberId,
    kind: a.kind,
    amount_cents: a.amount_cents,
    currency: a.currency || ctx.user.default_currency || 'BDT',
    occurred_at: new Date().toISOString(),
    memo: a.memo || '',
    source: 'telegram_voice',
    source_message_id: String($('Combine Inputs').item.json.message_id || ''),
    raw_transcript: $('Combine Inputs').item.json.text || '',
    confirmed_by_owner: a.confidence >= 0.7
  });
}
if (rows.length) {
  await fetch(SUPA + '/rest/v1/entries', {
    method: 'POST',
    headers: { apikey: KEY, Authorization: 'Bearer ' + KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify(rows)
  });
}
return [{ json: { written: rows, intent, ctx } }];

function fmt(n,c){const m=(n/100).toLocaleString('en-US',{maximumFractionDigits:2});return ['BDT','USD','EUR'].includes(c)?`${c} ${m}`:`${m} ${c}`;}
const intent = $json.intent;
const lang = intent.language;
const a = (intent.actions || [])[0] || { kind: 'unknown' };
let text;
if (lang === 'bn') {
  text = a.kind === 'lend' ? `${a.counterparty_name||'ওনাকে'} ${fmt(a.amount_cents,a.currency)} ধার দিয়েছ। মনে রাখলাম।`
       : a.kind === 'borrow' ? `${a.counterparty_name||'ওনার থেকে'} ${fmt(a.amount_cents,a.currency)} ধার নিয়েছ। পরে জানাবে।`
       : a.kind === 'settle' ? `${fmt(a.amount_cents,a.currency)} শোধ করলে।`
       : a.kind === 'expense' ? `${fmt(a.amount_cents,a.currency)} খরচ। মনে রাখলাম।`
       : 'আরেকটু পরিষ্কার বলবেন?';
} else {
  text = a.kind === 'lend' ? `Logged. Lent ${fmt(a.amount_cents,a.currency)} to ${a.counterparty_name||'them'}.`
       : a.kind === 'borrow' ? `Logged. Borrowed ${fmt(a.amount_cents,a.currency)} from ${a.counterparty_name||'them'}.`
       : a.kind === 'settle' ? `Logged. Settled ${fmt(a.amount_cents,a.currency)}.`
       : a.kind === 'expense' ? `Logged. ${fmt(a.amount_cents,a.currency)} spent.`
       : 'Could you say that again, please?';
}
return [{ json: { chatId: $json.ctx && $json.ctx.user ? $('Combine Inputs').item.json.message.chat.id : 0, text, lang } }];
